// Rebuild one resolved Decimator battle from the protocol's public logs.
//
// Since audit 92a1358d0 the Decimator is a shared-dice craps battle
// (DegenerusGameDecimatorModule.sol). Sealing emits DecimatorResolved with the
// round's word; each heads entry's run emits DecimatorRun with its peak;
// ranking emits DecimatorRanked; every winner's credit emits DecimatorClaimed.
// A winner's score is its stack (its last DecBurnRecorded) times that peak, so
// the receipt can order the paid winners exactly. Raw FLIP destroyed comes from
// FLIP.DecimatorBurn.

import { CHAIN, CONTRACTS, ETH_DIVISOR } from './chain-config.js';
import { readProviderBlockNumber, sharedReadProvider } from './read-provider.js';
import { ethers } from './contracts.js';
import { readIndexedDecimatorWindowStartBlock } from './decimator.js';

const GAME_EVENTS = [
  'event DecBurnRecorded(address indexed player,uint24 indexed lvl,uint64 indexed entryId,uint256 baseAmount,uint256 credited,uint256 stack,uint32 chips)',
  'event DecimatorResolved(uint24 indexed lvl,uint256 rngWord,uint256 poolWei,uint64 entrants)',
  'event DecimatorRun(uint24 indexed lvl,uint64 indexed entryId,uint256 normalizedPeak)',
  'event DecimatorRanked(uint24 indexed lvl,uint64 champion,uint8 winners)',
  'event DecimatorClaimed(address indexed player,uint24 indexed lvl,uint64 indexed entryId,uint256 amountWei,uint256 halfPasses)',
];
const FLIP_EVENTS = [
  'event DecimatorBurn(address indexed player,uint256 amountBurned,uint64 entryId)',
];

// DecimatorModule.SCALE: every run starts from this bankroll, so a peak over it is the
// run's best multiple and stack x peak / SCALE is the score in stack units.
export const DECIMATOR_RUN_SCALE_WEI = 3_000n * 10n ** 18n;

const gameInterface = new ethers.Interface(GAME_EVENTS);
const flipInterface = new ethers.Interface(FLIP_EVENTS);
// Base's public RPC caps and rate-limits wide eth_getLogs reads. Stay below
// the same 2,000-block boundary used by the live Decimator entry reader.
const DRAW_LOG_CHUNK_BLOCKS = 1_800;
let readProvider = null;
let providerOverride = null;

function integer(value, fallback = 0) {
  const parsed = Number(value);
  return Number.isInteger(parsed) ? parsed : fallback;
}

function logOrder(left, right) {
  return Number(left?.blockNumber || 0) - Number(right?.blockNumber || 0)
    || Number(left?.index ?? left?.logIndex ?? 0) - Number(right?.index ?? right?.logIndex ?? 0);
}

function provider() {
  if (providerOverride) return providerOverride;
  if (!readProvider) {
    readProvider = sharedReadProvider();  // C15: shared batched read stream
  }
  return readProvider;
}

function levelTopic(level) {
  return ethers.zeroPadValue(ethers.toBeHex(level), 32);
}

async function boundedLogs(reader, filter, fromBlock, toBlock) {
  const from = Number(fromBlock);
  const to = Number(toBlock);
  if (!Number.isInteger(from) || !Number.isInteger(to) || from > to) return [];
  const rows = [];
  for (let start = from; start <= to; start += DRAW_LOG_CHUNK_BLOCKS) {
    const end = Math.min(to, start + DRAW_LOG_CHUNK_BLOCKS - 1);
    const chunk = await reader.getLogs({ ...filter, fromBlock: start, toBlock: end });
    if (Array.isArray(chunk)) rows.push(...chunk);
  }
  return rows;
}

async function latestBoundedLog(reader, filter, fromBlock, toBlock) {
  const floor = Number(fromBlock);
  const ceiling = Number(toBlock);
  if (!Number.isInteger(floor) || !Number.isInteger(ceiling) || floor > ceiling) return null;
  for (let end = ceiling; end >= floor; end -= DRAW_LOG_CHUNK_BLOCKS) {
    const start = Math.max(floor, end - DRAW_LOG_CHUNK_BLOCKS + 1);
    const chunk = await reader.getLogs({ ...filter, fromBlock: start, toBlock: end });
    const latest = [...(Array.isArray(chunk) ? chunk : [])].sort(logOrder).at(-1);
    if (latest) return latest;
  }
  return null;
}

function parsed(logs, iface, name, lvl) {
  return [...(Array.isArray(logs) ? logs : [])].sort(logOrder).flatMap((log) => {
    try {
      const row = iface.parseLog(log);
      return row?.name === name && (lvl == null || Number(row.args.lvl) === lvl) ? [{ log, args: row.args }] : [];
    } catch (_error) { return []; }
  });
}

/** A run's best multiple of its starting bankroll, to two decimals (floored). */
export function decimatorPeakMultiple(peakWei) {
  try {
    const hundredths = (BigInt(peakWei) * 100n) / DECIMATOR_RUN_SCALE_WEI;
    return `${hundredths / 100n}.${String(hundredths % 100n).padStart(2, '0')}`;
  } catch (_error) { return null; }
}

/** DecimatorModule._run's final coin: heads plays the dice, tails sits out. */
export function decimatorCoinHeads(rngWord, level, entryId) {
  const hash = ethers.keccak256(ethers.AbiCoder.defaultAbiCoder().encode(
    ['bytes32', 'uint256', 'uint24', 'uint64'],
    [ethers.id('decimator.battle.final-coin.v1'), BigInt(rngWord), Number(level), BigInt(entryId)],
  ));
  return (BigInt(hash) & 1n) === 1n;
}

/** Stack x peak in stack units: the exact order the contract ranks winners by. */
export function decimatorScoreWei(stackWei, peakWei) {
  try { return (BigInt(stackWei) * BigInt(peakWei)) / DECIMATOR_RUN_SCALE_WEI; }
  catch (_error) { return 0n; }
}

/** Build the receipt snapshot from already-fetched logs. */
export function buildDecimatorDrawSnapshot({
  level,
  player,
  gameLogs,
  flipLogs,
  network = CHAIN.name,
  gameAddress = CONTRACTS.GAME,
  ethDisplayScale = ETH_DIVISOR,
} = {}) {
  const lvl = integer(level, -1);
  if (lvl <= 0) throw new Error('Invalid Decimator level.');

  const resolved = parsed(gameLogs, gameInterface, 'DecimatorResolved', lvl).at(-1);
  if (!resolved) throw new Error(`Level ${lvl} Decimator result is not indexed on-chain yet.`);
  const ranked = parsed(gameLogs, gameInterface, 'DecimatorRanked', lvl).at(-1) || null;

  // One entry per wallet: its last DecBurnRecorded carries the final stack and board.
  const entries = new Map();
  for (const { args } of parsed(gameLogs, gameInterface, 'DecBurnRecorded', lvl)) {
    entries.set(String(args.entryId), {
      entryId: String(args.entryId),
      address: String(args.player).toLowerCase(),
      stack: BigInt(args.stack),
      chips: Number(args.chips) >>> 0,
    });
  }
  const peaks = new Map();
  for (const { args } of parsed(gameLogs, gameInterface, 'DecimatorRun', lvl)) {
    peaks.set(String(args.entryId), BigInt(args.normalizedPeak));
  }
  const winners = parsed(gameLogs, gameInterface, 'DecimatorClaimed', lvl).map(({ args }) => {
    const id = String(args.entryId);
    const stack = entries.get(id)?.stack ?? 0n;
    const peak = peaks.get(id) ?? 0n;
    return {
      entryId: id,
      address: String(args.player).toLowerCase(),
      stack: stack.toString(),
      peak: peak.toString(),
      peakMultiple: decimatorPeakMultiple(peak),
      score: decimatorScoreWei(stack, peak).toString(),
      ethWei: BigInt(args.amountWei).toString(),
      halfPasses: BigInt(args.halfPasses).toString(),
      champion: ranked != null && String(ranked.args.champion) === id,
    };
  }).sort((left, right) => {
    // Equal scores order by the contract's random tiebreak; the entry id is a stable stand-in.
    const a = BigInt(left.score); const b = BigInt(right.score);
    if (a !== b) return a > b ? -1 : 1;
    return Number(right.champion) - Number(left.champion) || Number(left.entryId) - Number(right.entryId);
  }).map((row, index) => ({ ...row, rank: index + 1 }));

  let totalFlipBurned = 0n;
  for (const { args } of parsed(flipLogs, flipInterface, 'DecimatorBurn', null)) {
    totalFlipBurned += BigInt(args.amountBurned);
  }

  const viewed = String(player || '').toLowerCase();
  let you = null;
  for (const entry of entries.values()) {
    if (entry.address !== viewed) continue;
    const peak = peaks.get(entry.entryId) ?? null;
    const won = winners.find((row) => row.entryId === entry.entryId) || null;
    you = {
      entryId: entry.entryId,
      address: entry.address,
      coin: decimatorCoinHeads(resolved.args.rngWord, lvl, entry.entryId) ? 'heads' : 'tails',
      stack: entry.stack.toString(),
      chips: entry.chips,
      peak: peak == null ? null : peak.toString(),
      peakMultiple: peak == null ? null : decimatorPeakMultiple(peak),
      score: peak == null ? null : decimatorScoreWei(entry.stack, peak).toString(),
      rank: won?.rank ?? null,
      winner: Boolean(won),
      ethWei: won?.ethWei ?? '0',
      halfPasses: won?.halfPasses ?? '0',
    };
  }

  return {
    network,
    ethDisplayScale: BigInt(ethDisplayScale || 1).toString(),
    gameAddress,
    level: lvl,
    resolvedBlock: Number(resolved.log.blockNumber),
    rngWord: BigInt(resolved.args.rngWord).toString(),
    poolWei: BigInt(resolved.args.poolWei).toString(),
    entrants: Number(resolved.args.entrants),
    totalFlipBurned: totalFlipBurned.toString(),
    ranked: ranked != null,
    winnerCount: ranked == null ? null : Number(ranked.args.winners),
    championEntryId: ranked == null ? null : String(ranked.args.champion),
    // Every paid winner, ranked by score. `winnerCount` above counts the unpaid ones too.
    winners,
    you,
  };
}

export async function loadDecimatorDrawSnapshot({ level, player, fromBlock: knownFromBlock } = {}) {
  const lvl = integer(level, -1);
  if (lvl <= 0) throw new Error('Invalid Decimator level.');
  const reader = provider();
  const topic = levelTopic(lvl);
  const head = Number(await readProviderBlockNumber(reader));
  if (!Number.isInteger(head) || head < 0) {
    throw new Error('The latest Decimator block is unavailable.');
  }
  let fromBlock = Number(knownFromBlock);
  if (!Number.isInteger(fromBlock) || fromBlock < 0) {
    try { fromBlock = Number(await readIndexedDecimatorWindowStartBlock(lvl)); }
    catch (_error) { fromBlock = Number.NaN; }
  }
  if (!Number.isInteger(fromBlock) || fromBlock < 0 || fromBlock > head) {
    fromBlock = Math.max(0, Number(CHAIN.deployBlock || 0));
  }

  // Search newest chunks first for the seal so a missing index boundary still
  // finds a just-finished event without walking the whole deployment.
  const event = (name) => gameInterface.getEvent(name).topicHash;
  const resolvedLog = await latestBoundedLog(reader, {
    address: CONTRACTS.GAME,
    topics: [event('DecimatorResolved'), topic],
  }, fromBlock, head);
  if (!resolvedLog) throw new Error(`Level ${lvl} Decimator result is still syncing.`);
  const sealBlock = Number(resolvedLog.blockNumber);
  // Entries close at the seal; runs, the ranking and every credit come after it.
  const [burnLogs, settleLogs] = await Promise.all([
    boundedLogs(reader, { address: CONTRACTS.GAME, topics: [event('DecBurnRecorded'), null, topic] }, fromBlock, sealBlock),
    boundedLogs(reader, {
      address: CONTRACTS.GAME,
      topics: [[event('DecimatorRun'), event('DecimatorRanked'), event('DecimatorClaimed')]],
    }, sealBlock, head),
  ]);
  const firstBurnBlock = burnLogs.reduce(
    (lowest, log) => Math.min(lowest, Number(log.blockNumber)),
    sealBlock,
  );
  const flipLogs = await boundedLogs(reader, {
    address: CONTRACTS.COIN,
    topics: [flipInterface.getEvent('DecimatorBurn').topicHash],
  }, firstBurnBlock, sealBlock);
  return buildDecimatorDrawSnapshot({
    level: lvl,
    player,
    gameLogs: [...burnLogs, resolvedLog, ...settleLogs],
    flipLogs,
  });
}

/** Test-only provider seam. */
export function __setDecimatorDrawProviderForTest(next) {
  providerOverride = next || null;
}

export function __resetDecimatorDrawProviderForTest() {
  providerOverride = null;
}
